-- COSMO DataMind 示例数据库
-- 用法: sqlite3 demo.db < examples/sample_db.sql
--
-- 造一个最小但完整的制造业数仓切片:3 张维表 + 2 张事实表 + 1 张汇总表。
-- 刻意保留两处「真实数据才有」的特征,好让本体构建有东西可裁决:
--   1) 表间无声明外键 —— 关系只能靠取值重叠自证(这正是半自动构建要解决的)
--   2) 同一实体在不同表里列名不同(line_id / prod_line_id) —— 考验列名词根判定

DROP TABLE IF EXISTS dim_product;
CREATE TABLE dim_product (
  prod_id      INTEGER PRIMARY KEY,
  prod_name    TEXT,      -- 产品名称
  prod_line_id INTEGER,   -- 所属产线(与 dim_production_line.line_id 同源,列名不同)
  unit_price   REAL       -- 单价(元)
);

DROP TABLE IF EXISTS dim_production_line;
CREATE TABLE dim_production_line (
  line_id     INTEGER PRIMARY KEY,
  line_name   TEXT,       -- 产线名称
  workshop    TEXT,       -- 所属车间
  capacity    INTEGER     -- 日产能(台)
);

DROP TABLE IF EXISTS dim_customer;
CREATE TABLE dim_customer (
  cust_id     INTEGER PRIMARY KEY,
  cust_name   TEXT,       -- 客户名称
  region      TEXT,       -- 大区
  grade       TEXT        -- 客户等级
);

DROP TABLE IF EXISTS fact_production_output;
CREATE TABLE fact_production_output (
  output_id   INTEGER PRIMARY KEY,
  stat_date   TEXT,       -- 统计日期 YYYY-MM-DD
  line_id     INTEGER,    -- 产线
  prod_id     INTEGER,    -- 产品
  qty_plan    INTEGER,    -- 计划产量
  qty_actual  INTEGER,    -- 实际产量
  qty_pass    INTEGER     -- 合格数
);

DROP TABLE IF EXISTS fact_sales_order;
CREATE TABLE fact_sales_order (
  order_id    INTEGER PRIMARY KEY,
  order_date  TEXT,       -- 下单日期
  cust_id     INTEGER,    -- 客户
  prod_id     INTEGER,    -- 产品
  qty         INTEGER,    -- 数量
  amount      REAL,       -- 订单金额(元)
  cost        REAL        -- 成本(元)
);

DROP TABLE IF EXISTS dws_production_daily;
CREATE TABLE dws_production_daily (
  stat_date     TEXT,     -- 统计日期
  line_id       INTEGER,  -- 产线
  qty_actual    INTEGER,  -- 当日实际产量
  pass_rate     REAL      -- 当日直通率
);





  SELECT stat_date, line_id, SUM(qty_actual), ROUND(1.0*SUM(qty_pass)/SUM(qty_actual),4)
  FROM fact_production_output GROUP BY stat_date, line_id;
